#include <stdio.h>
#include <stdlib.h>

int main() {
    int size;
    printf("How many numbers? ");
    size = 5;

    int *arr = (int*)malloc(sizeof(int) * size);

    for(int i=0; i<size; i++) {
        arr[i] = i * 10;
        printf("%d ", arr[i]);
    }

    free(arr);
    return 0;
}
